CREATE TABLE finance.invoice (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    invoice_number varchar(40) NOT NULL,
    student_id uuid,
    bill_to_user_id uuid,
    bill_to_name varchar(200) NOT NULL,
    invoice_date date NOT NULL,
    due_date date,
    currency_id uuid NOT NULL,
    subtotal numeric(14,2) NOT NULL DEFAULT 0,
    discount_total numeric(14,2) NOT NULL DEFAULT 0,
    tax_total numeric(14,2) NOT NULL DEFAULT 0,
    total numeric(14,2) NOT NULL DEFAULT 0,
    amount_paid numeric(14,2) NOT NULL DEFAULT 0,
    status varchar(30) NOT NULL DEFAULT  'draft',
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    invoice_type varchar(20) NOT NULL DEFAULT 'invoice',
    credit_for_invoice_id uuid,
    posted_at timestamptz,
    cancelled_at timestamptz,
    document_file_id uuid,
    CONSTRAINT pk_invoice PRIMARY KEY (id),
    CONSTRAINT ck_invoice_status CHECK (status IN ('draft', 'posted', 'partially_paid', 'paid', 'cancelled')),
    CONSTRAINT uq_invoice_1 UNIQUE (tenant_id, invoice_number),
    CONSTRAINT ck_invoice_1 CHECK (student_id IS NOT NULL OR bill_to_user_id IS NOT NULL),
    CONSTRAINT ck_invoice_type CHECK (invoice_type IN ('invoice', 'credit_note')),
    CONSTRAINT ck_invoice_credit CHECK (invoice_type <> 'credit_note' OR credit_for_invoice_id IS NOT NULL),
    CONSTRAINT ck_invoice_totals CHECK (subtotal >= 0 AND discount_total >= 0 AND tax_total >= 0 AND total >= 0 AND amount_paid >= 0),
    CONSTRAINT uq_invoice_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT uq_invoice_id_currency UNIQUE (id, currency_id),
    CONSTRAINT ck_invoice_no_self_credit CHECK (credit_for_invoice_id IS NULL OR credit_for_invoice_id <> id)
);
COMMENT ON TABLE finance.invoice IS 'Invoice raised to a student / guardian / user (fees, library fines, purchases).';
