CREATE TABLE finance.coupon (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    code varchar(40) NOT NULL,
    discount_type varchar(30) NOT NULL,
    percentage_discount numeric(5,2),
    fixed_discount numeric(14,2),
    expires_on date,
    usage_limit integer,
    redemption_count integer NOT NULL DEFAULT 0,
    is_enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_coupon PRIMARY KEY (id),
    CONSTRAINT ck_coupon_discount_type CHECK (discount_type IN ('percentage', 'fixed_amount')),
    CONSTRAINT ck_coupon_1 CHECK ((discount_type = 'percentage' AND percentage_discount IS NOT NULL) OR (discount_type = 'fixed_amount' AND fixed_discount IS NOT NULL)),
    CONSTRAINT uq_coupon_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT ck_coupon_redemption_rule CHECK (usage_limit IS NULL OR redemption_count <= usage_limit)
);
