COMMENT ON COLUMN finance.coupon_scope.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.coupon_scope.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN finance.coupon_scope.row_version IS 'Optimistic-locking version.';

CREATE TABLE finance.payment (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    payer_user_id uuid,
    purpose varchar(30) NOT NULL,
    invoice_id uuid,
    lms_course_id uuid,
    lms_cohort_id uuid,
    admission_application_id uuid,
    gateway_name varchar(60),
    gateway_order_id varchar(120),
    gateway_payment_id varchar(120),
    original_amount numeric(14,2),
    discount_amount numeric(14,2) NOT NULL DEFAULT 0,
    amount numeric(14,2) NOT NULL,
    amount_with_tax numeric(14,2),
    currency_id uuid NOT NULL,
    coupon_id uuid,
    coupon_code varchar(40),
    billing_name varchar(200) NOT NULL,
    billing_address_id uuid,
    tax_registration_number varchar(30),
    tax_identity_enc text,
    acquisition_source_id uuid,
    payer_consent boolean NOT NULL DEFAULT false,
    status varchar(30) NOT NULL DEFAULT  'initiated',
    received_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    payer_person_id uuid,
    payer_name varchar(200),
    payment_method varchar(30) NOT NULL DEFAULT 'gateway',
    receipt_number varchar(40),
    instrument_reference varchar(80),
    instrument_date date,
    bank_name varchar(120),
    gateway_account_id uuid,
    received_by_user_id uuid,
    gateway_currency varchar(3),
    gateway_amount_minor bigint,
    CONSTRAINT pk_payment PRIMARY KEY (id),
    CONSTRAINT ck_payment_purpose CHECK (purpose IN ('invoice', 'fees', 'lms_course', 'lms_cohort', 'lms_certificate', 'admission')),
    CONSTRAINT ck_payment_amount_rule CHECK (amount>=0),
    CONSTRAINT ck_payment_status CHECK (status IN ('initiated', 'received', 'failed', 'refunded')),
    CONSTRAINT ck_payment_2 CHECK (purpose NOT IN ('lms_course','lms_certificate') OR lms_course_id IS NOT NULL),
    CONSTRAINT ck_payment_3 CHECK (purpose <> 'lms_cohort' OR lms_cohort_id IS NOT NULL),
    CONSTRAINT ck_payment_4 CHECK (purpose <> 'admission' OR admission_application_id IS NOT NULL),
    CONSTRAINT ck_payment_method CHECK (payment_method IN ('gateway', 'cash', 'cheque', 'dd', 'bank_transfer', 'card_pos', 'adjustment')),
    CONSTRAINT ck_payment_payer CHECK (payer_user_id IS NOT NULL OR payer_person_id IS NOT NULL OR payer_name IS NOT NULL),
    CONSTRAINT uq_payment_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT uq_payment_id_currency UNIQUE (id, currency_id),
    CONSTRAINT ck_payment_invoice_purpose CHECK (purpose <> 'invoice' OR invoice_id IS NOT NULL)
);
COMMENT ON TABLE finance.payment IS 'Money received: fees, LMS course / cohort / certificate purchases, admission fees.';
COMMENT ON COLUMN finance.payment.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.payment.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.payment.institution_id IS 'Institution receiving the money.';
COMMENT ON COLUMN finance.payment.payer_user_id IS 'Payer.';
COMMENT ON COLUMN finance.payment.purpose IS 'What the payment is for.';
COMMENT ON COLUMN finance.payment.invoice_id IS 'Invoice settled.';
COMMENT ON COLUMN finance.payment.lms_course_id IS 'Course purchased.';
COMMENT ON COLUMN finance.payment.lms_cohort_id IS 'Cohort purchased.';
COMMENT ON COLUMN finance.payment.admission_application_id IS 'Application paid for.';
COMMENT ON COLUMN finance.payment.gateway_name IS 'Payment gateway.';
COMMENT ON COLUMN finance.payment.gateway_order_id IS 'Gateway order id.';
COMMENT ON COLUMN finance.payment.gateway_payment_id IS 'Gateway payment id.';
COMMENT ON COLUMN finance.payment.original_amount IS 'Amount before discount.';
COMMENT ON COLUMN finance.payment.discount_amount IS 'Discount.';
COMMENT ON COLUMN finance.payment.amount IS 'Amount payable before tax.';
COMMENT ON COLUMN finance.payment.amount_with_tax IS 'Amount including tax.';
COMMENT ON COLUMN finance.payment.currency_id IS 'Currency.';
COMMENT ON COLUMN finance.payment.coupon_id IS 'Coupon used.';
COMMENT ON COLUMN finance.payment.coupon_code IS 'Coupon code entered.';
COMMENT ON COLUMN finance.payment.billing_name IS 'Billing name.';
COMMENT ON COLUMN finance.payment.billing_address_id IS 'Billing address.';
COMMENT ON COLUMN finance.payment.tax_registration_number IS 'Buyer''s tax registration (e.g. GSTIN).';
COMMENT ON COLUMN finance.payment.tax_identity_enc IS 'Buyer''s tax identity number (e.g. PAN), encrypted.';
COMMENT ON COLUMN finance.payment.acquisition_source_id IS 'Marketing source.';
COMMENT ON COLUMN finance.payment.payer_consent IS 'Payer accepted terms.';
COMMENT ON COLUMN finance.payment.status IS 'State.';
COMMENT ON COLUMN finance.payment.received_at IS 'When the money was received.';
COMMENT ON COLUMN finance.payment.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.payment.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.payment.updated_at IS 'Last update time.';
COMMENT ON COLUMN finance.payment.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.payment.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN finance.payment.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN finance.payment.payer_person_id IS 'Paying person when they have no user account (counter payments). At least one of payer_user_id / payer_person_id / payer_name must be set.';
COMMENT ON COLUMN finance.payment.payer_name IS 'Free-text payer name for counter payments with no person record.';
COMMENT ON COLUMN finance.payment.payment_method IS 'How the money arrived: gateway, cash, cheque, dd, bank_transfer, card_pos or adjustment.';
COMMENT ON COLUMN finance.payment.receipt_number IS 'Tenant receipt number issued for offline/counter payments; unique per tenant when set.';
COMMENT ON COLUMN finance.payment.instrument_reference IS 'Cheque/DD/transfer reference number for offline payments.';
COMMENT ON COLUMN finance.payment.instrument_date IS 'Date on the cheque/DD/transfer instrument.';
COMMENT ON COLUMN finance.payment.bank_name IS 'Drawee bank for cheque/DD payments.';
COMMENT ON COLUMN finance.payment.gateway_account_id IS 'Gateway account (merchant credentials) the payment was taken on.';
COMMENT ON COLUMN finance.payment.received_by_user_id IS 'Staff user who recorded a counter payment.';
COMMENT ON COLUMN finance.payment.gateway_currency IS 'ISO 4217 code of the order opened at the gateway; a notification of another currency is refused.';
COMMENT ON COLUMN finance.payment.gateway_amount_minor IS 'Amount of the order opened at the gateway, in minor units (paise); a notification of another amount is refused.';

-- Intra-module foreign keys
ALTER TABLE finance.fee_plan_installment ADD CONSTRAINT fk_fee_plan_installment_fee_plan_id FOREIGN KEY (fee_plan_id, tenant_id) REFERENCES finance.fee_plan (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_fee_plan_installment_fee_plan_id ON finance.fee_plan_installment (fee_plan_id);
ALTER TABLE finance.fee_plan_installment_component ADD CONSTRAINT fk_fee_plan_installment_component_installment_id FOREIGN KEY (installment_id, tenant_id) REFERENCES finance.fee_plan_installment (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_fee_plan_installment_component_installment_id ON finance.fee_plan_installment_component (installment_id);
ALTER TABLE finance.fee_plan_installment_component ADD CONSTRAINT fk_fee_plan_installment_component_fee_head_id FOREIGN KEY (fee_head_id, tenant_id) REFERENCES finance.fee_head (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_fee_plan_installment_component_fee_head_id ON finance.fee_plan_installment_component (fee_head_id);
ALTER TABLE finance.student_fee_due ADD CONSTRAINT fk_student_fee_due_installment_id FOREIGN KEY (installment_id, tenant_id) REFERENCES finance.fee_plan_installment (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_student_fee_due_installment_id ON finance.student_fee_due (installment_id);
ALTER TABLE finance.student_fee_due ADD CONSTRAINT fk_student_fee_due_fee_head_id FOREIGN KEY (fee_head_id, tenant_id) REFERENCES finance.fee_head (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_student_fee_due_fee_head_id ON finance.student_fee_due (fee_head_id);
ALTER TABLE finance.student_fee_due ADD CONSTRAINT fk_student_fee_due_invoice_id FOREIGN KEY (invoice_id, tenant_id) REFERENCES finance.invoice (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_student_fee_due_invoice_id ON finance.student_fee_due (invoice_id);
ALTER TABLE finance.invoice_line ADD CONSTRAINT fk_invoice_line_invoice_id FOREIGN KEY (invoice_id, tenant_id) REFERENCES finance.invoice (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_invoice_line_invoice_id ON finance.invoice_line (invoice_id);
ALTER TABLE finance.invoice_line ADD CONSTRAINT fk_invoice_line_fee_head_id FOREIGN KEY (fee_head_id, tenant_id) REFERENCES finance.fee_head (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_invoice_line_fee_head_id ON finance.invoice_line (fee_head_id);
ALTER TABLE finance.coupon_scope ADD CONSTRAINT fk_coupon_scope_coupon_id FOREIGN KEY (coupon_id, tenant_id) REFERENCES finance.coupon (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_coupon_scope_coupon_id ON finance.coupon_scope (coupon_id);
ALTER TABLE finance.payment ADD CONSTRAINT fk_payment_invoice_id FOREIGN KEY (invoice_id, tenant_id) REFERENCES finance.invoice (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_payment_invoice_id ON finance.payment (invoice_id);
ALTER TABLE finance.payment ADD CONSTRAINT fk_payment_coupon_id FOREIGN KEY (coupon_id, tenant_id) REFERENCES finance.coupon (id, tenant_id) ON DELETE SET NULL (coupon_id);
CREATE INDEX ix_payment_coupon_id ON finance.payment (coupon_id);

-- === P0-01 / P0-02: payments ledger, fee structures, relocated fee links ===

CREATE TABLE finance.payment_gateway_account (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    gateway_name varchar(60) NOT NULL,
    display_name varchar(150) NOT NULL,
    merchant_id varchar(120),
    key_id varchar(120),
    key_secret_enc text,
    webhook_secret_enc text,
    currency_id uuid,
    is_default boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_payment_gateway_account PRIMARY KEY (id),
    CONSTRAINT uq_payment_gateway_account_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE finance.payment_gateway_account IS 'Payment-gateway merchant account configured by a tenant (per institution when needed).';
COMMENT ON COLUMN finance.payment_gateway_account.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.payment_gateway_account.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.payment_gateway_account.institution_id IS 'Institution (NULL = tenant-wide).';
COMMENT ON COLUMN finance.payment_gateway_account.gateway_name IS 'Gateway identifier (razorpay, stripe, payu...).';
COMMENT ON COLUMN finance.payment_gateway_account.display_name IS 'Admin-facing name of this account.';
COMMENT ON COLUMN finance.payment_gateway_account.merchant_id IS 'Merchant/account id at the gateway.';
COMMENT ON COLUMN finance.payment_gateway_account.key_id IS 'API key id (public part).';
COMMENT ON COLUMN finance.payment_gateway_account.key_secret_enc IS 'API key secret (application-encrypted envelope; write-only through the API).';
COMMENT ON COLUMN finance.payment_gateway_account.webhook_secret_enc IS 'Webhook signing secret (application-encrypted envelope; write-only through the API).';
COMMENT ON COLUMN finance.payment_gateway_account.currency_id IS 'Settlement currency.';
COMMENT ON COLUMN finance.payment_gateway_account.is_default IS 'Default account for the tenant/institution.';
COMMENT ON COLUMN finance.payment_gateway_account.is_active IS 'Whether usable for new payments.';
COMMENT ON COLUMN finance.payment_gateway_account.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.payment_gateway_account.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.payment_gateway_account.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN finance.payment_gateway_account.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN finance.payment_gateway_account.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN finance.payment_gateway_account.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE finance.payment_allocation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    invoice_id uuid,
    student_fee_due_id uuid,
    amount numeric(14,2) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    currency_id uuid NOT NULL,
    CONSTRAINT pk_payment_allocation PRIMARY KEY (id),
    CONSTRAINT ck_payment_allocation_amount_rule CHECK (amount > 0),
    CONSTRAINT ck_payment_allocation_target CHECK ((invoice_id IS NOT NULL) <> (student_fee_due_id IS NOT NULL))
);
COMMENT ON TABLE finance.payment_allocation IS 'Split of one payment across invoices / fee dues. Sum of allocations never exceeds the payment amount (application-enforced). Ledger row: never updated, reversed by finance.refund.';
COMMENT ON COLUMN finance.payment_allocation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.payment_allocation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.payment_allocation.payment_id IS 'Payment being allocated.';
COMMENT ON COLUMN finance.payment_allocation.invoice_id IS 'Invoice this slice settles (exactly one of invoice_id / student_fee_due_id).';
COMMENT ON COLUMN finance.payment_allocation.student_fee_due_id IS 'Fee due this slice settles (exactly one of invoice_id / student_fee_due_id).';
COMMENT ON COLUMN finance.payment_allocation.amount IS 'Allocated amount in the payment currency.';
COMMENT ON COLUMN finance.payment_allocation.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.payment_allocation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.payment_allocation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN finance.payment_allocation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN finance.payment_allocation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN finance.payment_allocation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
COMMENT ON COLUMN finance.payment_allocation.currency_id IS 'Currency of the slice; forced equal to both the payment''''s and the target''''s currency by composite FKs.';

CREATE TABLE finance.refund (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    amount numeric(14,2) NOT NULL,
    reason varchar(300),
    status varchar(30) NOT NULL DEFAULT 'initiated',
    gateway_refund_id varchar(120),
    refund_method varchar(30) NOT NULL DEFAULT 'gateway',
    refunded_by_user_id uuid,
    refunded_at timestamptz,
    request_key uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_refund PRIMARY KEY (id),
    CONSTRAINT ck_refund_amount_rule CHECK (amount > 0),
    CONSTRAINT ck_refund_status CHECK (status IN ('initiated', 'processed', 'failed', 'cancelled')),
    CONSTRAINT ck_refund_method CHECK (refund_method IN ('gateway', 'cash', 'cheque', 'bank_transfer', 'adjustment'))
);
COMMENT ON TABLE finance.refund IS 'Refund against a payment (full or partial). Ledger row: never deleted.';
COMMENT ON COLUMN finance.refund.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.refund.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.refund.payment_id IS 'Payment being refunded.';
COMMENT ON COLUMN finance.refund.amount IS 'Refunded amount; total refunds never exceed the payment amount (application-enforced).';
COMMENT ON COLUMN finance.refund.reason IS 'Why the refund was made.';
COMMENT ON COLUMN finance.refund.status IS 'initiated / processed / failed / cancelled.';
COMMENT ON COLUMN finance.refund.gateway_refund_id IS 'Refund id at the gateway for gateway refunds.';
COMMENT ON COLUMN finance.refund.refund_method IS 'How the money went back.';
COMMENT ON COLUMN finance.refund.refunded_by_user_id IS 'Staff user who initiated the refund.';
COMMENT ON COLUMN finance.refund.refunded_at IS 'When the refund completed.';
COMMENT ON COLUMN finance.refund.request_key IS 'Idempotency-Key of the request that opened the refund; a retry finds this row instead of refunding twice.';
COMMENT ON COLUMN finance.refund.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.refund.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.refund.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN finance.refund.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN finance.refund.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN finance.refund.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE finance.gateway_event (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    gateway_account_id uuid,
    gateway_name varchar(60) NOT NULL,
    gateway_event_id varchar(150),
    event_type varchar(80) NOT NULL,
    payment_id uuid,
    raw_payload text,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_gateway_event PRIMARY KEY (id)
);
COMMENT ON TABLE finance.gateway_event IS 'Webhook/event received from a payment gateway, kept for idempotent processing and dispute evidence. Append-only.';
COMMENT ON COLUMN finance.gateway_event.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.gateway_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.gateway_event.gateway_account_id IS 'Gateway account the event belongs to.';
COMMENT ON COLUMN finance.gateway_event.gateway_name IS 'Gateway identifier.';
COMMENT ON COLUMN finance.gateway_event.gateway_event_id IS 'Event id assigned by the gateway; used to deduplicate deliveries.';
COMMENT ON COLUMN finance.gateway_event.event_type IS 'Gateway event type (payment.captured, refund.processed...).';
COMMENT ON COLUMN finance.gateway_event.payment_id IS 'Payment the event was matched to, once resolved.';
COMMENT ON COLUMN finance.gateway_event.raw_payload IS 'Raw event body as received (no interpretation).';
COMMENT ON COLUMN finance.gateway_event.received_at IS 'When the event was received.';
COMMENT ON COLUMN finance.gateway_event.processed_at IS 'When the event was successfully processed.';
COMMENT ON COLUMN finance.gateway_event.processing_error IS 'Last processing error, if any.';
COMMENT ON COLUMN finance.gateway_event.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.gateway_event.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.gateway_event.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN finance.gateway_event.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN finance.gateway_event.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN finance.gateway_event.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE finance.fee_structure (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    academic_year_id uuid NOT NULL,
    grade_level_id uuid,
    program_id uuid,
    fee_plan_id uuid NOT NULL,
    name varchar(150) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'draft',
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_fee_structure PRIMARY KEY (id),
    CONSTRAINT ck_fee_structure_status CHECK (status IN ('draft', 'published', 'archived')),
    CONSTRAINT uq_fee_structure_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE finance.fee_structure IS 'What a class/program costs in an academic year: binds a fee plan to the year and the class or program. Publishing a structure is what generates student_fee_due rows for enrolled students.';
COMMENT ON COLUMN finance.fee_structure.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN finance.fee_structure.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN finance.fee_structure.institution_id IS 'Institution (NULL = tenant-wide).';
COMMENT ON COLUMN finance.fee_structure.academic_year_id IS 'Academic year the structure prices.';
COMMENT ON COLUMN finance.fee_structure.grade_level_id IS 'K-12 grade level (class) the structure applies to (NULL when program-scoped or tenant-wide).';
COMMENT ON COLUMN finance.fee_structure.program_id IS 'Higher-ed program the structure applies to (NULL when class-scoped or tenant-wide).';
COMMENT ON COLUMN finance.fee_structure.fee_plan_id IS 'Fee plan (heads + installments) charged.';
COMMENT ON COLUMN finance.fee_structure.name IS 'Admin-facing name.';
COMMENT ON COLUMN finance.fee_structure.status IS 'draft / published / archived. Dues are generated on publish.';
COMMENT ON COLUMN finance.fee_structure.created_at IS 'Row creation time.';
COMMENT ON COLUMN finance.fee_structure.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN finance.fee_structure.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN finance.fee_structure.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN finance.fee_structure.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN finance.fee_structure.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE finance.fee_concession (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    student_id uuid NOT NULL,
    academic_year_id uuid NOT NULL,
    fee_head_id uuid,
    concession_type varchar(20) NOT NULL,
    concession_value numeric(14,2) NOT NULL,
    reason varchar(300),
    approved_by_user_id uuid,
    status varchar(20) NOT NULL DEFAULT 'active',
    valid_from date,
    valid_until date,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_fee_concession PRIMARY KEY (id),
    CONSTRAINT ck_fee_concession_type CHECK (concession_type IN ('percent', 'amount')),
    CONSTRAINT ck_fee_concession_status CHECK (status IN ('active', 'revoked')),
    CONSTRAINT ck_fee_concession_value_rule CHECK (concession_value >= 0),
    CONSTRAINT uq_fee_concession_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT ck_fee_concession_percent_rule CHECK (concession_type <> 'percent' OR concession_value <= 100)
);
COMMENT ON TABLE finance.fee_concession IS 'Scholarship / discount granted to one student for an academic year, applied when dues are generated or regenerated.';
